import { configureToiFetch, toiFetch } from '@toi/fetch';

type HostConfig = Parameters<typeof configureToiFetch>[0];
const hostConfig = (globalThis as typeof globalThis & { __TOI_FETCH_CONFIG__?: HostConfig }).__TOI_FETCH_CONFIG__;
if (!hostConfig) throw new Error('Preview host configuration missing: __TOI_FETCH_CONFIG__');
configureToiFetch(hostConfig);

export interface Order {
  id: string;
  customerId: string;
  amount: number;
  status: string;
  createdAt?: string;
  note?: string;
}

export class AccessRevokedError extends Error {
  override name = 'ToiAccessRevokedError';
  status = 404;
  code = 'PROJECT_NOT_FOUND';
  constructor(message = '이 프로젝트에 접근할 수 없어요. 멤버에서 제거되었거나 권한이 바뀌었을 수 있어요') {
    super(message);
  }
}

export class OrderNotFoundError extends Error {
  override name = 'OrderNotFoundError';
  status = 404;
  constructor(message = '주문을 찾을 수 없습니다.') {
    super(message);
  }
}

export async function getOrder(id: string, reason: string): Promise<Order> {
  let response: Response;
  try {
    response = await toiFetch('orders', `/orders/${encodeURIComponent(id)}`, { reason });
  } catch (err: any) {
    if (
      err?.name === 'ToiAccessRevokedError' ||
      err?.code === 'PROJECT_NOT_FOUND' ||
      (err?.status === 404 && err?.code === 'PROJECT_NOT_FOUND')
    ) {
      throw new AccessRevokedError();
    }
    throw err;
  }

  if (!response.ok) {
    let errorData: any = {};
    try {
      errorData = await response.json();
    } catch {
      // ignore JSON parse failure
    }

    if (response.status === 404 && errorData?.code === 'PROJECT_NOT_FOUND') {
      throw new AccessRevokedError();
    }
    if (response.status === 404) {
      throw new OrderNotFoundError();
    }
    throw new Error(errorData?.message || `요청 실패: ${response.status}`);
  }

  const data = await response.json();
  return data;
}

import React, { useState } from 'react';
import { Button, TextField, Badge } from '@toi/tds';
import { getOrder, Order } from './api';

export default function App() {
  const [orderId, setOrderId] = useState('O001');
  const [reason, setReason] = useState('주문 O001 상세 조회');
  const [order, setOrder] = useState<Order | null>(null);
  const [loading, setLoading] = useState(false);
  const [accessError, setAccessError] = useState<string | null>(null);
  const [notFound, setNotFound] = useState(false);
  const [generalError, setGeneralError] = useState<string | null>(null);

  const isReasonValid = reason.trim().length >= 5;

  const handleSearch = async (e?: React.FormEvent) => {
    if (e) {
      e.preventDefault();
    }
    if (!isReasonValid) {
      return;
    }

    setLoading(true);
    setAccessError(null);
    setNotFound(false);
    setGeneralError(null);

    try {
      const data = await getOrder(orderId.trim(), reason.trim());
      setOrder(data);
    } catch (err: any) {
      setOrder(null);
      if (err?.name === 'ToiAccessRevokedError' || err?.code === 'PROJECT_NOT_FOUND') {
        setAccessError('이 프로젝트에 접근할 수 없어요. 멤버에서 제거되었거나 권한이 바뀌었을 수 있어요');
      } else if (err?.name === 'OrderNotFoundError' || err?.status === 404) {
        setNotFound(true);
      } else {
        setGeneralError(err?.message || '주문 정보를 불러오는 중 오류가 발생했습니다.');
      }
    } finally {
      setLoading(false);
    }
  };

  return (
    <main style={{ maxWidth: '800px', margin: '40px auto', padding: '0 20px', fontFamily: 'system-ui, -apple-system, sans-serif' }}>
      <header style={{ marginBottom: '24px' }}>
        <h1 style={{ fontSize: '24px', fontWeight: 700, margin: '0 0 8px 0', color: '#1a202c' }}>
          주문 상세 조회
        </h1>
        <p style={{ margin: 0, color: '#718096', fontSize: '14px' }}>
          주문 번호와 조회 사유를 입력하여 주문 정보를 조회합니다.
        </p>
      </header>

      <form
        onSubmit={handleSearch}
        style={{
          background: '#ffffff',
          border: '1px solid #e2e8f0',
          borderRadius: '10px',
          padding: '24px',
          boxShadow: '0 1px 3px rgba(0,0,0,0.05)',
          display: 'flex',
          flexDirection: 'column',
          gap: '16px'
        }}
      >
        <div style={{ display: 'flex', flexDirection: 'column', gap: '6px' }}>
          <TextField
            id="orderId"
            name="orderId"
            label="주문 ID"
            aria-label="주문 ID"
            placeholder="주문 ID를 입력하세요"
            value={orderId}
            onChange={(valOrEvent: any) => {
              const val = typeof valOrEvent === 'string' ? valOrEvent : valOrEvent?.target?.value ?? '';
              setOrderId(val);
            }}
          />
        </div>

        <div style={{ display: 'flex', flexDirection: 'column', gap: '6px' }}>
          <TextField
            id="reason"
            name="reason"
            label="조회 사유"
            aria-label="조회 사유"
            placeholder="조회 사유를 5자 이상 입력하세요"
            value={reason}
            onChange={(valOrEvent: any) => {
              const val = typeof valOrEvent === 'string' ? valOrEvent : valOrEvent?.target?.value ?? '';
              setReason(val);
            }}
          />
          {!isReasonValid && (
            <p style={{ color: '#e53e3e', fontSize: '13px', margin: '2px 0 0 0' }}>
              조회 사유는 최소 5자 이상 입력해야 합니다.
            </p>
          )}
        </div>

        <div style={{ display: 'flex', justifyContent: 'flex-end', marginTop: '8px' }}>
          <Button
            type="submit"
            disabled={loading || !isReasonValid || !orderId.trim()}
          >
            조회
          </Button>
        </div>
      </form>

      {loading && (
        <div style={{ textAlign: 'center', padding: '32px 0', color: '#718096' }}>
          주문 정보를 불러오는 중입니다...
        </div>
      )}

      {accessError && (
        <div
          role="alert"
          style={{
            marginTop: '24px',
            padding: '16px 20px',
            backgroundColor: '#fff5f5',
            border: '1px solid #fed7d7',
            borderRadius: '8px',
            color: '#c53030',
            fontSize: '14px',
            lineHeight: 1.5
          }}
        >
          {accessError}
        </div>
      )}

      {!accessError && notFound && (
        <div
          role="status"
          style={{
            marginTop: '24px',
            padding: '24px',
            textAlign: 'center',
            backgroundColor: '#f7fafc',
            border: '1px solid #e2e8f0',
            borderRadius: '8px',
            color: '#718096',
            fontSize: '14px'
          }}
        >
          주문을 찾을 수 없습니다. (주문 ID: {orderId})
        </div>
      )}

      {!accessError && generalError && (
        <div
          role="alert"
          style={{
            marginTop: '24px',
            padding: '16px 20px',
            backgroundColor: '#fffaf0',
            border: '1px solid #feebc8',
            borderRadius: '8px',
            color: '#c05621',
            fontSize: '14px'
          }}
        >
          {generalError}
        </div>
      )}

      {!loading && !accessError && order && (
        <section
          aria-label="주문 상세"
          style={{
            marginTop: '24px',
            background: '#ffffff',
            border: '1px solid #e2e8f0',
            borderRadius: '10px',
            overflow: 'hidden',
            boxShadow: '0 1px 3px rgba(0,0,0,0.05)'
          }}
        >
          <div style={{ padding: '16px 24px', borderBottom: '1px solid #e2e8f0', backgroundColor: '#f8fafc' }}>
            <h2 style={{ margin: 0, fontSize: '16px', fontWeight: 600, color: '#2d3748' }}>
              주문 상세 내역
            </h2>
          </div>
          <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left', fontSize: '14px' }}>
            <tbody>
              <tr style={{ borderBottom: '1px solid #edf2f7' }}>
                <th style={{ padding: '14px 24px', width: '160px', color: '#4a5568', fontWeight: 600, backgroundColor: '#fdfdfe' }}>
                  <span>id</span>
                </th>
                <td data-testid="id" style={{ padding: '14px 24px', color: '#1a202c' }}>
                  {order.id}
                </td>
              </tr>
              <tr style={{ borderBottom: '1px solid #edf2f7' }}>
                <th style={{ padding: '14px 24px', width: '160px', color: '#4a5568', fontWeight: 600, backgroundColor: '#fdfdfe' }}>
                  <span>customerId</span>
                </th>
                <td data-testid="customerId" style={{ padding: '14px 24px', color: '#1a202c' }}>
                  {order.customerId}
                </td>
              </tr>
              <tr style={{ borderBottom: '1px solid #edf2f7' }}>
                <th style={{ padding: '14px 24px', width: '160px', color: '#4a5568', fontWeight: 600, backgroundColor: '#fdfdfe' }}>
                  <span>amount</span>
                </th>
                <td data-testid="amount" style={{ padding: '14px 24px', color: '#1a202c' }}>
                  {order.amount}
                </td>
              </tr>
              <tr style={{ borderBottom: '1px solid #edf2f7' }}>
                <th style={{ padding: '14px 24px', width: '160px', color: '#4a5568', fontWeight: 600, backgroundColor: '#fdfdfe' }}>
                  <span>status</span>
                </th>
                <td data-testid="status" style={{ padding: '14px 24px', color: '#1a202c' }}>
                  <Badge>{order.status}</Badge>
                </td>
              </tr>
              <tr>
                <th style={{ padding: '14px 24px', width: '160px', color: '#4a5568', fontWeight: 600, backgroundColor: '#fdfdfe' }}>
                  <span>note</span>
                </th>
                <td data-testid="note" style={{ padding: '14px 24px', color: '#1a202c' }}>
                  {order.note ?? ''}
                </td>
              </tr>
            </tbody>
          </table>
        </section>
      )}
    </main>
  );
}

